WITH cleaned AS (SELECT id, channel, starts_on, ends_on, discount_pct, ROUND(discount_pct, 0) AS discount_pct_rounded, COALESCE(channel, 'UNKNOWN') AS channel_filled FROM promotions WHERE ends_on > DATE '2023-11-30') SELECT DATE_TRUNC('MONTH', starts_on) AS activity_month, MAX(discount_pct_rounded) AS max_discount_pct_rounded, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, APPROX_PERCENTILE(discount_pct_rounded, ARRAY(0.25, 0.5, 0.75)) AS discount_pct_rounded_quartiles, SIZE(COLLECT_SET(channel)) AS num_channels FROM cleaned GROUP BY DATE_TRUNC('MONTH', starts_on) ORDER BY num_channels NULLS FIRST;
